//! `cargo xtask gen tokens`: CSS variables and TypeScript names from `design/tokens.json` (ADR-0010).

use std::fmt::Write as _;

use super::token_file::{BaseToken, BaseValue, ShadowLayer, Theme, TokenFile};
use super::{Generated, write_all};
use crate::repo::Repo;

const TS_HEADER: &str =
    "// Generated by `cargo xtask gen tokens` from design/tokens.json. Do not edit by hand.
";

/// Where the CSS goes: the browser app's copy and the design pages' copy.
const CSS_OUTPUTS: [&str; 2] = ["web/packages/ui/src/tokens.css", "docs/design/tokens.css"];
const TS_OUTPUT: &str = "web/packages/ui/src/tokens.ts";

/// The paths [`generate`] writes.
pub(crate) fn output_paths() -> Vec<&'static str> {
    let mut paths = CSS_OUTPUTS.to_vec();
    paths.push(TS_OUTPUT);
    paths
}

pub(crate) fn run(repo: &Repo) -> anyhow::Result<Vec<String>> {
    let tokens = TokenFile::load(repo)?;
    write_all(repo, &generate(&tokens))
}

pub(crate) fn generate(tokens: &TokenFile) -> Vec<Generated> {
    let css = css(tokens);
    let mut outputs: Vec<Generated> = CSS_OUTPUTS
        .iter()
        .map(|path| Generated::new(path, css.clone()))
        .collect();
    outputs.push(Generated::new(TS_OUTPUT, typescript(tokens)));
    outputs
}

fn css(tokens: &TokenFile) -> String {
    let light = theme_named(tokens, &tokens.default_light);
    let dark = theme_named(tokens, &tokens.default_dark);
    let mut out = css_header(tokens);
    out.push_str(":root {\n");
    for token in &tokens.base {
        let _ = writeln!(out, "  --{}: {};", token.name, base_value(token));
    }
    theme_declarations(&mut out, light, "  ");
    out.push_str("}\n\n");
    out.push_str("@media (prefers-color-scheme: dark) {\n");
    out.push_str("  :root:not([data-theme=\"light\"]) {\n");
    theme_declarations(&mut out, dark, "    ");
    out.push_str("  }\n}\n\n");
    out.push_str(":root[data-theme=\"dark\"] {\n");
    theme_declarations(&mut out, dark, "  ");
    out.push_str("}\n");
    for theme in &tokens.themes {
        let _ = write!(out, "\n:root[data-look=\"{}\"] {{\n", theme.name);
        theme_declarations(&mut out, theme, "  ");
        out.push_str("}\n");
    }
    out
}

/// The generated-file notice followed by an explanation built from the token data.
fn css_header(tokens: &TokenFile) -> String {
    let names: Vec<String> = tokens
        .themes
        .iter()
        .map(|theme| title_case(&theme.name))
        .collect();
    let fonts: Vec<&str> = tokens
        .base
        .iter()
        .filter_map(|token| match &token.value {
            BaseValue::FontFamily(families) => families.first().map(String::as_str),
            BaseValue::Dimension(_) => None,
        })
        .collect();
    format!(
        "/* Generated by `cargo xtask gen tokens` from design/tokens.json. Do not edit by hand.
   {count} built-in themes: {names}. Pages set <html data-look=\"…\">;
   without it, \"Match my device\" falls back to {light} (light) / {dark} (dark).
   Load fonts separately: {fonts}. */
",
        count = names.len(),
        names = names.join(", "),
        light = title_case(&tokens.default_light),
        dark = title_case(&tokens.default_dark),
        fonts = fonts.join(" + "),
    )
}

fn title_case(name: &str) -> String {
    let mut letters = name.chars();
    letters
        .next()
        .map(|first| first.to_uppercase().chain(letters).collect())
        .unwrap_or_default()
}

fn theme_named<'a>(tokens: &'a TokenFile, name: &str) -> &'a Theme {
    // `TokenFile::parse` already checked that both default themes exist.
    tokens
        .themes
        .iter()
        .find(|theme| theme.name == name)
        .unwrap_or(&tokens.themes[0])
}

fn theme_declarations(out: &mut String, theme: &Theme, indent: &str) {
    for (name, value) in &theme.colors {
        let _ = writeln!(out, "{indent}--{name}: {};", value.to_ascii_lowercase());
    }
    let _ = writeln!(out, "{indent}--shadow: {};", shadow_value(&theme.shadow));
    let _ = writeln!(out, "{indent}color-scheme: {};", theme.color_scheme);
}

fn base_value(token: &BaseToken) -> String {
    match &token.value {
        BaseValue::Dimension(value) => value.clone(),
        BaseValue::FontFamily(names) => names
            .iter()
            .map(|name| {
                if name.contains(' ') {
                    format!("\"{name}\"")
                } else {
                    name.clone()
                }
            })
            .collect::<Vec<_>>()
            .join(", "),
    }
}

fn shadow_value(layers: &[ShadowLayer]) -> String {
    layers
        .iter()
        .map(|layer| {
            format!(
                "{} {} {} {} {}",
                zero(&layer.offset_x),
                zero(&layer.offset_y),
                zero(&layer.blur),
                zero(&layer.spread),
                layer.color.to_ascii_lowercase()
            )
        })
        .collect::<Vec<_>>()
        .join(", ")
}

/// `0px` is written as plain `0`, as CSS formatters expect.
fn zero(length: &str) -> &str {
    if length == "0px" { "0" } else { length }
}

fn typescript(tokens: &TokenFile) -> String {
    let mut out = String::from(TS_HEADER);
    let themes: Vec<String> = tokens
        .themes
        .iter()
        .map(|theme| format!("\"{}\"", theme.name))
        .collect();
    let _ = write!(
        out,
        "\nexport const themeIds = [{}] as const;\nexport type ThemeId = (typeof themeIds)[number];\n",
        themes.join(", ")
    );
    let _ = write!(
        out,
        "\nexport const defaultLightTheme: ThemeId = \"{}\";\nexport const defaultDarkTheme: ThemeId = \"{}\";\n",
        tokens.default_light, tokens.default_dark
    );
    out.push_str("\nexport const colorTokens = [\n");
    for (name, _) in &tokens.themes[0].colors {
        let _ = writeln!(out, "  \"{name}\",");
    }
    out.push_str("] as const;\nexport type ColorToken = (typeof colorTokens)[number];\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn generated_files_are_up_to_date() {
        let repo = Repo::discover().unwrap();
        let tokens = TokenFile::load(&repo).unwrap();
        for output in generate(&tokens) {
            let on_disk = std::fs::read_to_string(repo.path(output.path)).unwrap();
            assert_eq!(
                on_disk, output.content,
                "{} is stale; run `cargo xtask gen tokens`",
                output.path
            );
        }
    }

    #[test]
    fn css_has_every_theme_and_the_device_fallback() {
        let repo = Repo::discover().unwrap();
        let css = css(&TokenFile::load(&repo).unwrap());
        for theme in ["daylight", "paper", "dusk", "midnight"] {
            assert!(css.contains(&format!(":root[data-look=\"{theme}\"]")));
        }
        assert!(css.contains("prefers-color-scheme: dark"));
    }
}
